    ["{{#if x}}{{else}}{{else}}{{/if}}", /Duplicate 'else'.*line 1, column 19/],
  ])("reports structural errors for %s", (template, expected) => {
    expect(() => render(template, { x: true })).toThrow(expected);
  });
});

